// Answer the webinar's OWN registration questions (read by the previous node)
// from the sheet row, matching each question by its title. Nothing about the
// titles is configured anywhere: trailing spaces, "U.S." vs "US", radio answer
// wording all come from Zoom itself.
const clean = (s) => (s ?? '').toString().replace(/[\x00-\x1F\x7F]/g, ' ').trim();
const norm = (s) => clean(s).toLowerCase().replace(/[^a-z0-9]/g, '');
const b = $('Webhook').item.json.body;
const token = $('Get Zoom token (Marketing)').item.json.access_token;
const resp = $json.body && typeof $json.body === 'object' ? $json.body : {};
const stdQs = Array.isArray(resp.questions) ? resp.questions : [];
const customQs = Array.isArray(resp.custom_questions) ? resp.custom_questions : [];

const v = {
  phone: clean(b.phone).slice(0, 20),
  job: clean(b.job_title).slice(0, 128) || 'Other',
  practice: clean(b.practice_name).slice(0, 128),
  question: clean(b.questions).slice(0, 128) || '-',
  country: clean(b.country).toUpperCase(),
  interest: clean(b.member_interest).toLowerCase(),
};
const COUNTRY = { US: ['us', 'usa', 'unitedstates'], CA: ['canada'], GB: ['uk', 'unitedkingdom'], AU: ['australia'], NZ: ['newzealand'], OTHER: ['other'] };
const INTEREST = { yes: ['yes'], already: ['already'], no: ['no', 'not'] };

// First answer whose normalised text equals, starts with, or contains a keyword.
const pick = (answers, words) => {
  const n = (answers || []).map((a) => ({ a, n: norm(a) }));
  for (const w of words) { const h = n.find((x) => x.n === w); if (h) return h.a; }
  for (const w of words) { const h = n.find((x) => x.n.startsWith(w)); if (h) return h.a; }
  for (const w of words) { const h = n.find((x) => x.n.includes(w)); if (h) return h.a; }
  return null;
};

const custom = [];
for (const q of customQs) {
  const t = norm(q.title);
  const choice = Array.isArray(q.answers) && q.answers.length > 0;
  let val = null;
  if (/mobile|phone|cell/.test(t)) val = v.phone;
  else if (/jobtitle|role|position|describe/.test(t)) val = v.job;
  else if (/practice|company|organi|business/.test(t)) val = v.practice;
  else if (/country|location|where/.test(t)) val = choice ? (pick(q.answers, COUNTRY[v.country] || COUNTRY.OTHER) || pick(q.answers, COUNTRY.OTHER)) : v.country;
  else if (/member|join/.test(t)) val = choice ? pick(q.answers, INTEREST[v.interest] || INTEREST.no) : v.interest;
  else if (/question|ask|panel|topic|learn|hope|discuss/.test(t)) val = v.question;
  if (choice && val && !q.answers.includes(val)) val = pick(q.answers, [norm(val)]);
  if (!val && q.required) val = choice ? q.answers[q.answers.length - 1] : '-';
  if (val) custom.push({ title: q.title, value: String(val).slice(0, 128) });
}

const payload = {
  first_name: clean(b.first_name).slice(0, 64) || 'Member',
  last_name: clean(b.last_name).slice(0, 64) || '-',
  email: clean(b.email).toLowerCase(),
  phone: v.phone,
  org: v.practice,
  job_title: v.job,
  custom_questions: custom,
  auto_approve: true,
};
// Standard Zoom fields the webinar marks required.
for (const q of stdQs) {
  if (!q.required) continue;
  const f = q.field_name;
  if (f === 'last_name' || f === 'phone' || f === 'org' || f === 'job_title') continue;
  if (f === 'country') payload.country = /^[A-Z]{2}$/.test(v.country) ? v.country : 'US';
  else if (f === 'comments') payload.comments = v.question;
  else if (!(f in payload)) payload[f] = '-';
}
return [{ json: { access_token: token, webinar_id: clean(b.webinar_id), payload, questions_seen: customQs.map((q) => q.title) } }];

// Turn Zoom's answer into the three sheet columns.
const r = $json;
const code = r.statusCode ?? r.status ?? 0;
const body = r.body ?? {};
const ok = code >= 200 && code < 300 && body.registrant_id;
const b = $('Webhook').item.json.body;
return [{ json: {
  registration_id: b.registration_id,
  sheet_name: b.sheet_name,
  zoom_status: ok ? 'Registered' : 'Failed',
  zoom_registrant_id: ok ? String(body.registrant_id) : '',
  zoom_error: ok ? '' : `${code} ${body.code ?? ''} ${body.message ?? JSON.stringify(body).slice(0, 300)}`.trim()
} }];
